// ===== Extrai o e-mail e monta o prompt de triagem =====
const g = $('Preparar anexos').first().json;
const cfg = $('Config').first().json;
const reqs = $('Ler REQUISITOS').all().map(i => i.json);
const texto = String(g.text || g.textPlain || g.snippet || '');
const assunto = String(g.subject || g.Subject || '');
let remetente = '';
const f = g.from;
if (typeof f === 'string') remetente = f;
else if (f && f.value && f.value[0]) remetente = f.value[0].address || '';
else if (f && f.text) remetente = f.text;
remetente = (remetente.match(/[\w.+-]+@[\w.-]+/) || [remetente])[0];
const emailId = g.id || g.messageId || '';
const tabela = reqs.map(r => '- ' + r['CATEGORIA'] + ' (palavras-chave: ' + r['PALAVRAS-CHAVE'] + ') => obrigatórios: ' + r['CAMPOS OBRIGATÓRIOS']).join('\n');
const SYSTEM = "Você é o triador de pedidos de compra da construtora Prisbel. Você recebe uma tabela de categorias com campos obrigatórios e um e-mail. Responda SOMENTE com JSON válido, sem texto adicional, no formato: {\"e_pedido\": true|false, \"obra\": \"nome\"|null, \"urgente\": true|false, \"motivo_urgencia\": \"texto\"|null, \"itens\": [{\"descricao\": \"texto completo do item como pedido\", \"quantidade\": numero|null, \"unidade\": \"un|par|cx|kg|m|...\", \"categoria\": \"uma da tabela\", \"campos_faltantes\": [\"...\"]}]}. Regras: e_pedido=true somente se o e-mail solicita compra/cotação de materiais. Para cada item, verifique os campos obrigatórios da categoria: os ausentes entram em campos_faltantes. Se quantidade ausente, inclua 'quantidade'. Se o e-mail indicar urgência sem justificativa, urgente=true e motivo_urgencia=null. NUNCA invente dados REGRA FINAL (prevalece sobre a tabela de categorias): se a descricao ja contem a informacao que o campo obrigatorio pede, o campo ESTA ATENDIDO — nao liste em campos_faltantes. Exemplos: 'CP II-32' atende classe/uso do cimento; 'CA-50' atende tipo do vergalhao; 'AC2' atende classe da argamassa; tijolo/bloco 'de vedacao' NAO exige resistencia MPa (so os estruturais exigem); 'de vedacao' atende o campo tipo/uso. REGRAS ADICIONAIS: (a) a descricao de cada item deve preservar TODAS as especificações mencionadas na mensagem — dimensões, classe, resistência, bitola, cor, marca, modelo (ex.: 'blocos de concreto estrutural 14x19x39 4,5 MPa', nunca só 'blocos de concreto'); (b) designações comerciais que JÁ SÃO a classe do produto não geram pendência: CP2/CP II/CP III/CP IV/CP V (cimento), AC1/AC2/AC3 (argamassa colante), CA-50/CA-60 (vergalhão) — se presentes, o campo classe/tipo está atendido; que não estão no e-mail. Se um item não casar com nenhuma categoria, use GERAL. Regras de bom senso: (1) unidade implícita na descrição (latas, caixas, rolos, sacos, pares, barras, metros) NÃO é campo faltante — considere-a a unidade do item; (2) aplique somente os campos obrigatórios que fazem sentido para o subtipo do item (ex.: barramento é exigência de quadro de distribuição, não de caixa de luz; CA é exigência de EPI de proteção, não de uniforme comum); (3) justificativas de urgência implícitas como prazo de cronograma, equipe parada ou concretagem marcada CONTAM como motivo_urgencia — extraia a frase. Se houver ANEXOS (PDF de requisição ou foto de lista de materiais), LEIA-OS e extraia os itens também deles — o corpo do e-mail pode estar vazio e o pedido inteiro estar no anexo. Regras adicionais (calibragem 21/07): (a) números no ASSUNTO junto de palavras como PEDIDO, REQUISIÇÃO, RM ou SOLICITAÇÃO (ex.: 'PEDIDO 150', 'requisicao 514') são o NÚMERO DO DOCUMENTO, nunca quantidade de item — se a quantidade real não aparecer no corpo ou anexo, deixe quantidade null e inclua 'quantidade' em campos_faltantes; (b) sacos, latas, barras, rolos, galões, baldes, fardos, pacotes, caixas, pares, metros, m2, m3, kg e toneladas SÃO unidades de medida válidas — 'saco' é a unidade padrão de cimento, argamassa, gesso e cal; quando presente, use-a e NÃO marque unidade como faltante; (c) imagens que são apenas logotipo ou assinatura de e-mail devem ser IGNORADAS como fonte de itens; se a única fonte de informação for o assunto do e-mail, extraia o material mas marque 'confirmar quantidade e unidade na requisição original' em campos_faltantes.";
const user = 'TABELA DE CATEGORIAS:\n' + tabela + '\n\nASSUNTO:\n' + assunto + '\n\nCORPO DO E-MAIL:\n' + texto;
return [{ json: { remetente, assunto, email_id: emailId,
  body: { system_instruction: { parts: [{ text: SYSTEM }] }, contents: [{ role: 'user', parts: (function(){ const ps = [{ text: user }]; for (const a of (g.anexos || [])) ps.push({ inline_data: { mime_type: a.mime, data: a.data } }); return ps; })() }],
  generationConfig: { temperature: 0, maxOutputTokens: 8192, responseMimeType: 'application/json', thinkingConfig: { thinkingBudget: 0 } } } } }];

// ===== Processa a triagem: fila, rascunhos, aviso =====
const cfg = $('Config').first().json;
const m = $('Montar prompt triagem').first().json;
const forn = $('Ler FORNECEDORES').all().map(i => i.json);
const pedidos = $('Ler PEDIDOS').all().map(i => i.json);
let t = {};
try { const raw = $json.candidates?.[0]?.content?.parts?.[0]?.text || ''; t = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { t = { e_pedido: false, parse_error: true }; }
const agora = new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
const dh = String(agora.getDate()).padStart(2,'0') + '/' + String(agora.getMonth()+1).padStart(2,'0') + '/' + agora.getFullYear() + ' ' + String(agora.getHours()).padStart(2,'0') + ':' + String(agora.getMinutes()).padStart(2,'0');
if (!t.e_pedido) {
  return [{ json: { tipo: 'nao_pedido', email_id: m.email_id, linhas: [], rascunhos: [],
    aviso_para: cfg.EMAIL_DANIELA, aviso_assunto: '[Bella] E-mail não classificado como pedido' + (t.parse_error ? ' (erro de leitura)' : ''),
    aviso_corpo: 'Assunto: ' + m.assunto + '\nRemetente: ' + m.remetente + '\nNenhuma ação tomada — verifique manualmente se necessário.' } }];
}
let num = 0; for (const p of pedidos) { const n = Number(p['Nº PEDIDO']); if (n > num) num = n; } num++;
const urg = t.urgente === true; const urgSemMotivo = urg && !t.motivo_urgencia;
const linhas = [], pendentes = [], completos = []; let seq = 0;
for (const it of (t.itens || [])) {
  const faltas = (it.campos_faltantes || []).slice();
  if (urgSemMotivo && !faltas.includes('motivo da urgência')) faltas.push('motivo da urgência');
  const status = faltas.length ? 'PENDENTE' : 'COMPLETO';
  linhas.push({ 'Nº PEDIDO': num, 'ITEM Nº': ++seq, 'DATA/HORA': dh, 'REMETENTE': m.remetente, 'NOME': '', 'OBRA': t.obra || '', 'URGENTE': urg ? 'SIM' : 'NÃO', 'MOTIVO URGÊNCIA': t.motivo_urgencia || '', 'ITEM': it.descricao || '', 'QUANT.': it.quantidade ?? '', 'UNID.': it.unidade || '', 'CATEGORIA': it.categoria || 'GERAL', 'STATUS': status, 'PENDÊNCIAS': faltas.join('; '), 'EMAIL_ID': m.email_id, 'OBS': '' });
  (faltas.length ? pendentes : completos).push({ ...it, faltas });
}
const rascunhos = [];
if (pendentes.length) {
  const corpo = 'Olá!\n\nRecebemos seu pedido (nº ' + num + '), mas faltam informações para prosseguir:\n\n' + pendentes.map(p => '• ' + (p.descricao || '?') + ' — falta: ' + p.faltas.join(', ')).join('\n') + '\n\nPor favor, responda este e-mail com os dados acima.\n\nBella — Assistente de Compras | Prisbel Construtora';
  rascunhos.push({ para: m.remetente, assunto: 'Pedido ' + num + ' — informações pendentes', corpo });
}
const porCat = {};
for (const c of completos) { const k = (c.categoria || 'GERAL').toUpperCase(); (porCat[k] = porCat[k] || []).push(c); }
for (const cat of Object.keys(porCat)) {
  const itens = porCat[cat];
  let f = forn.filter(x => String(x['CATEGORIA']).toUpperCase() === cat);
  if (!f.length) f = forn.filter(x => String(x['CATEGORIA']).toUpperCase() === 'GERAL');
  const dest = [...new Set(f.map(x => x['E-MAIL']).filter(Boolean))].join(', ') || cfg.EMAIL_DANIELA;
  const corpo = 'Prezados, bom dia!\n\nGentileza cotar os materiais abaixo, posto obra ' + (t.obra || '(a confirmar)') + ':\n\n' + itens.map(i => '• ' + (i.quantidade ?? '') + ' ' + (i.unidade || '') + ' — ' + i.descricao).join('\n') + '\n\nFavor informar prazo de entrega e condições de pagamento.\n\nAtenciosamente,\nBella — Assistente de Compras | Prisbel Construtora';
  rascunhos.push({ para: dest, assunto: 'Cotação ' + cat + ' — Pedido ' + num + (t.obra ? ' — obra ' + t.obra : ''), corpo });
}
const resumo = 'Pedido nº ' + num + ' triado.\nRemetente: ' + m.remetente + '\nObra: ' + (t.obra || '—') + '\nUrgente: ' + (urg ? ('SIM' + (t.motivo_urgencia ? ' (' + t.motivo_urgencia + ')' : ' — SEM MOTIVO INFORMADO')) : 'não') + '\nItens: ' + linhas.length + ' (' + completos.length + ' completos, ' + pendentes.length + ' pendentes)\nRascunhos prontos na caixa do ssysbot: ' + rascunhos.length + '\n\n' + linhas.map(l => '• [' + l['STATUS'] + '] ' + l['ITEM'] + (l['PENDÊNCIAS'] ? ' — falta: ' + l['PENDÊNCIAS'] : '')).join('\n');
return [{ json: { tipo: 'pedido', email_id: m.email_id, linhas, rascunhos, aviso_para: cfg.EMAIL_DANIELA, aviso_assunto: '[Bella] Pedido ' + num + ' triado — ' + completos.length + ' ok / ' + pendentes.length + ' pendente(s)', aviso_corpo: resumo } }];

const d = $json;
if (!d.linhas || !d.linhas.length) return [];
return d.linhas.map(l => ({ json: l }));

const d = $('Processar triagem').first().json;
if (!d.rascunhos || !d.rascunhos.length) return [];
return d.rascunhos.map(r => ({ json: r }));

// ===== Junta campos do e-mail + anexos (base64) para o Gemini =====
const trig = $('Gmail Trigger').first().json;
const out = { subject: trig.subject || '', text: trig.text || trig.snippet || '', from: trig.from, id: trig.id };
const anexos = [];
const item = $input.first();
const bin = item.binary || {};
for (const k of Object.keys(bin)) {
  const meta = bin[k];
  const mime = meta.mimeType || '';
  if (!/^application\/pdf|^image\//.test(mime)) continue;
  if (anexos.length >= 3) break;
  const buf = await this.helpers.getBinaryDataBuffer(0, k);
  if (buf.length > 6 * 1024 * 1024) continue;
  anexos.push({ mime, data: buf.toString('base64'), nome: meta.fileName || k });
}
out.anexos = anexos;
return [{ json: out }];

